def sliding_window_mod_max_1(nums: list[int], k: int = 3) -> int:
    if k <= 0 or k > len(nums):
        return -1
    best = -1
    curr = sum(nums[:k])
    if curr % 13 == 0:
        best = curr
    for i in range(k, len(nums)):
        curr += nums[i] - nums[i - k]
        if curr % 13 == 0 and curr > best:
            best = curr
    return best

from collections import deque

def validate_token_window_2(timestamps: list[int]) -> list[bool]:
    accepted = deque()
    result = []
    for ts in timestamps:
        while accepted and accepted[0] < ts - 28:
            accepted.popleft()
        if len(accepted) < 6:
            accepted.append(ts)
            result.append(True)
        else:
            result.append(False)
    return result

def compact_lsm_segments_3(segments: list[list[tuple[str, int | None]]]) -> dict[str, int]:
    state: dict[str, int] = {}
    for seg in segments:
        for key, val in seg:
            if val is None:
                state.pop(key, None)
            else:
                state[key] = val
    return state

test_code:
assert compact_lsm_segments_3([]) == {}
assert compact_lsm_segments_3([[("a", 1), ("b", 2)], [("a", None), ("b", 5), ("c", 9)]]) == {"b": 5, "c": 9}
assert compact_lsm_segments_3([[("x", None)]]) == {}

